CREATE TABLE users (id TEXT PRIMARY KEY, email TEXT NOT NULL UNIQUE COLLATE NOCASE, password_hash TEXT NOT NULL, password_salt TEXT NOT NULL, referral_code TEXT NOT NULL UNIQUE, role TEXT NOT NULL DEFAULT 'user' CHECK(role IN ('user','admin')), created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')));
CREATE TABLE sessions (id_hash TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, expires_at INTEGER NOT NULL, created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')));
CREATE INDEX sessions_user_id ON sessions(user_id); CREATE INDEX sessions_expiry ON sessions(expires_at);
CREATE TABLE products (id TEXT PRIMARY KEY, owner_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, name TEXT NOT NULL CHECK(length(name) BETWEEN 1 AND 100), url TEXT NOT NULL CHECK(length(url) BETWEEN 8 AND 2048), description TEXT NOT NULL CHECK(length(description) BETWEEN 1 AND 2000), stage TEXT NOT NULL DEFAULT 'idea' CHECK(stage IN ('idea','launched','growing')), status TEXT NOT NULL DEFAULT 'active' CHECK(status IN ('active','paused','archived')), created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')), updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')));
CREATE INDEX products_owner ON products(owner_id,created_at DESC); CREATE INDEX products_discover ON products(status,created_at DESC);
CREATE TABLE campaigns (id TEXT PRIMARY KEY, product_id TEXT NOT NULL REFERENCES products(id) ON DELETE CASCADE, owner_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, channel TEXT NOT NULL CHECK(length(channel) BETWEEN 1 AND 60), goal TEXT NOT NULL CHECK(length(goal) BETWEEN 1 AND 1000), status TEXT NOT NULL DEFAULT 'planned' CHECK(status IN ('planned','in_progress','completed','cancelled')), execution_mode TEXT NOT NULL DEFAULT 'manual' CHECK(execution_mode IN ('authorized_api','human_approval','manual','unavailable')), created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')), updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')));
CREATE INDEX campaigns_owner ON campaigns(owner_id,created_at DESC);
CREATE TABLE testers (id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, product_id TEXT NOT NULL REFERENCES products(id) ON DELETE CASCADE, consent_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')), status TEXT NOT NULL DEFAULT 'active' CHECK(status IN ('active','withdrawn')), UNIQUE(user_id,product_id));
CREATE TABLE feedback (id TEXT PRIMARY KEY, tester_id TEXT NOT NULL REFERENCES testers(id) ON DELETE CASCADE, product_id TEXT NOT NULL REFERENCES products(id) ON DELETE CASCADE, body TEXT NOT NULL CHECK(length(body) BETWEEN 1 AND 4000), created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')));
CREATE INDEX feedback_product ON feedback(product_id,created_at DESC);
CREATE TABLE referrals (id TEXT PRIMARY KEY, referrer_user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, referred_user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, product_id TEXT REFERENCES products(id) ON DELETE SET NULL, created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')), UNIQUE(referrer_user_id,referred_user_id));
CREATE TABLE analytics_events (id TEXT PRIMARY KEY, owner_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, product_id TEXT NOT NULL REFERENCES products(id) ON DELETE CASCADE, event_type TEXT NOT NULL CHECK(event_type IN ('visit','signup','activation','retention','feedback','campaign_activity')), source TEXT NOT NULL DEFAULT 'manual' CHECK(source IN ('manual','verified_integration')), event_key TEXT, occurred_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')), metadata_json TEXT NOT NULL DEFAULT '{}');
CREATE INDEX analytics_owner ON analytics_events(owner_id,occurred_at DESC); CREATE UNIQUE INDEX analytics_dedupe ON analytics_events(owner_id,event_key) WHERE event_key IS NOT NULL;
CREATE TABLE settings (key TEXT PRIMARY KEY, value_json TEXT NOT NULL, updated_by TEXT REFERENCES users(id), updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')));
CREATE TABLE audit_log (id TEXT PRIMARY KEY, actor_id TEXT REFERENCES users(id) ON DELETE SET NULL, action TEXT NOT NULL, target_type TEXT NOT NULL, target_id TEXT, metadata_json TEXT NOT NULL DEFAULT '{}', created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')));
CREATE TABLE rate_limits (key TEXT PRIMARY KEY, window_start INTEGER NOT NULL, count INTEGER NOT NULL);
CREATE INDEX audit_created ON audit_log(created_at DESC);

